#include <iostream>
#include <numeric>
using namespace std;

long long ipow(long long b, int e) {
    long long r = 1;
    while (e-- > 0) r *= b;
    return r;
}

int main() {
    int n, k;
    cin >> n >> k;
    long long num = 0;
    for (int m = 1; m <= k; m++) num += m * (ipow(m, n) - ipow(m - 1, n));
    long long den = ipow(k, n), g = gcd(num, den);
    cout << num / g << '/' << den / g << '\n';
    return 0;
}

